import{_ as r,l as p,o as e,c as h,v as o,p as i,x as t,d as l,i as s,S as n}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"微操作缓存","description":"","frontmatter":{"title":"微操作缓存","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/uop-cache.md","filePath":"cs/uop-cache.md","lastUpdated":1789023840000}'),d={name:"cs/uop-cache.md"};function u(E,a,_,B,m,A){const c=p("Mermaid");return e(),h("div",null,[a[1]||(a[1]=o('<h1 id="微操作缓存" tabindex="-1">微操作缓存 <a class="header-anchor" href="#微操作缓存" aria-label="Permalink to &quot;微操作缓存&quot;">​</a></h1><div class="epigraph"><p>变长宏指令译成定长微操作的代价很高；把已经译好的 uop 按热路径存起来，命中时取指不再走长度扫描。</p><footer>—— 据 Rotenberg, Bennett, and Smith, Trace Cache, MICRO 1996；Intel 对 uop cache 的公开描述 整理</footer></div><p><a href="/cs/fetch-decode-width">上一课</a>把前端带宽钉成供给上限，并点名变长译码是热点。本课不重做边界扫描。缺口是：<strong>用一块小的、按 uop 组织的 cache 记住最近译过的指令，命中则绕过传统译码器。</strong></p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>x86 核每拍要给重命名输送 4–6 个 uop，长度译码与微码协助在频率上很痛。热循环可能只有几十条宏指令，却被反复译码。缺口不是再加一条预译码流水，而是<strong>把「PC → uop 序列」缓存下来</strong>，用 SRAM 命中代替组合译码。</p><p><span class="marginnote">Trace cache 存的是动态执行痕迹，可跨越宏指令与分支。Intel Sandy Bridge 起公开的 DSB（decoded stream buffer / uop cache）更接近「按 IP 对齐的已译码 uop」，命中则 MITE 译码器睡觉。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>uop cache：索引取自指令指针（可虚拟），行内存若干 uop、下一块指针、是否以分支结束。命中：每拍从该结构弹出最多 \\(D_{\\text{uop}}\\) 个已译码 uop 进重命名，I-cache 与长度译码不参与。缺失：走普通取指/译码，填入 uop cache。自修改代码或 icache 作废时同步清空。</p>',8)),(e(),i(n,null,{default:t(()=>[s(c,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20IP%5B%22%E6%8C%87%E4%BB%A4%E6%8C%87%E9%92%88%22%5D%20--%3E%20UC%5B%22uop%20cache%22%5D%0A%20%20UC%20--%3E%7C%22%E5%91%BD%E4%B8%AD%22%7C%20REN%5B%22%E7%9B%B4%E6%8E%A5%E9%87%8D%E5%91%BD%E5%90%8D%22%5D%0A%20%20UC%20--%3E%7C%22%E7%BC%BA%E5%A4%B1%22%7C%20MITE%5B%22%E9%95%BF%E5%BA%A6%E8%AF%91%E7%A0%81%20%2B%20%E5%BE%AE%E7%A0%81%22%5D%0A%20%20MITE%20--%3E%20FILL%5B%22%E5%A1%AB%20uop%20cache%22%5D%0A%20%20MITE%20--%3E%20REN%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>与 I-cache 的包含关系：uop cache 是译码后的旁路，不替代指令页的一致性；SMC 必须两边都看到。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>前端 CPI：热路径上译码器功耗与延迟下降，有效 \\(D\\) 接近 uop 端口宽度。冷路径、巨函数、以及 uop 行装不下的超长指令序列仍走慢路径。容量以 uop 计，不是字节：一条复杂宏指令可能占多个槽，反而降低密度。</p><p>与<a href="/cs/gshare-predictor">分支预测</a>：uop 行往往在预测分支处截断，预测准才能连续弹出。误预测仍冲刷，只是重填可能再次命中 uop cache。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把循环流缓冲当成 uop cache 的子集讲完——LSB 是「锁定一个循环的 uop 流」，下一课。也不把 GPU 的指令 cache 写成 uop cache。微码 ROM 仍服务极少见的复杂指令，不进热 cache。</p><p>后课默认：热路径可以不经宏指令译码器。更小、锁定的循环还可以连 cache 标签比较都省掉。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>uop cache 缓存已译码微操作，绕过变长译码。</li><li>命中率取决于热路径大小与分支截断。</li><li>把循环锁定在更浅的缓冲里，是下一课 LSB。</li><li>出处：Rotenberg et al., <em>MICRO</em>, 1996；Intel 微结构公开文档中的 DSB。</li></ul>',9))])}const T=r(d,[["render",u]]);export{C as __pageData,T as default};
